-- Pandora Lunar share profiles: schema draft 1.
-- Target: Lunar project "LegendsOfTheGame's Project" (ref dehuwlbcfejuiijbpaao).
-- Status: APPLIED on 19 Nov 2026 (UTC) as migration 0001_share_profiles.
-- Do not edit this file. Put later changes in a new numbered migration.
--
-- Access model:
--   * Row Level Security is on for every table, with no policies.
--     The anon and authenticated roles cannot read or write any table.
--   * The Edge Function uses the service role for all writes
--     (share, re-share, delete, rename, restore).
--   * The public lookup is one SECURITY DEFINER function, get_share().
--     It returns only the public progress part, never the backup.
--
-- Secrets:
--   * The database never holds an owner key or a recovery code in plain form.
--     The Edge Function stores a SHA-256 hash (hex) of each one.
--   * The owner key is 32 random bytes, so a plain SHA-256 hash is sufficient.
--   * A recovery code must have at least 80 bits of entropy
--     (16 characters from the 32-character alphabet), because the wrapped data
--     key is stored next to its hash.
--   * The Ledger backup is encrypted in the browser. The server holds
--     ciphertext only.

create extension if not exists pg_cron;

-- Code format ---------------------------------------------------------------
-- Generated codes: 8 characters from ABCDEFGHJKLMNPQRSTUVWXYZ23456789
--   (no O, 0, I, 1). Shown as XXXX-XXXX, stored without the dash.
-- Custom codes (admin only): 1 to 8 characters, A-Z and 0-9.
-- All codes are stored in upper case with no dash.

create or replace function public.normalize_share_code(raw text)
returns text
language sql
immutable
as $$
  select upper(regexp_replace(coalesce(raw, ''), '[^A-Za-z0-9]', '', 'g'));
$$;

-- shares --------------------------------------------------------------------
-- One row for each share. The code is the current name of the share.

create table public.shares (
  id              uuid primary key default gen_random_uuid(),
  code            text not null unique
                  check (code ~ '^[A-Z0-9]{1,8}$'),
  is_custom       boolean not null default false,   -- true after an admin rename
  owner_key_hash  text not null
                  check (owner_key_hash ~ '^[0-9a-f]{64}$'),
  progress        jsonb not null,                    -- public part, not encrypted
  data_as_of      timestamptz not null,              -- time of the export
  shared_at       timestamptz not null default now(),-- time of the last upload
  is_permanent    boolean not null default false,
  expires_at      timestamptz,                       -- null when is_permanent
  created_at      timestamptz not null default now(),
  constraint shares_expiry_matches_permanent check (
    (is_permanent and expires_at is null) or
    (not is_permanent and expires_at is not null)
  ),
  -- Size limit for the public part. Change after a real export is measured.
  constraint shares_progress_size check (octet_length(progress::text) <= 262144)
);

create index shares_expires_at_idx on public.shares (expires_at)
  where expires_at is not null;

-- share_aliases -------------------------------------------------------------
-- An old code after an admin rename. It points to the same share,
-- so links that were given out continue to work.
-- An alias is deleted when its share is deleted.

create table public.share_aliases (
  alias       text primary key check (alias ~ '^[A-Z0-9]{1,8}$'),
  share_id    uuid not null references public.shares (id) on delete cascade,
  created_at  timestamptz not null default now()
);

create index share_aliases_share_id_idx on public.share_aliases (share_id);

-- reserved_codes ------------------------------------------------------------
-- Every code that was ever an alias, and every custom code. The Edge Function
-- must not issue a code from this table again, also after the share is deleted.

create table public.reserved_codes (
  code        text primary key check (code ~ '^[A-Z0-9]{1,8}$'),
  reason      text not null default 'alias',
  reserved_at timestamptz not null default now()
);

-- share_backups -------------------------------------------------------------
-- The whole Ledger backup (routine ticks, notes, settings), encrypted in the
-- browser with one random data key (DEK), AES-GCM.
-- owner_wrapped_dek: the DEK wrapped with a key derived from the owner key.

create table public.share_backups (
  share_id           uuid primary key references public.shares (id) on delete cascade,
  ciphertext         bytea not null,
  iv                 bytea not null check (octet_length(iv) = 12),
  owner_wrapped_dek  bytea not null,
  format_version     smallint not null default 1,
  updated_at         timestamptz not null default now(),
  -- Size limit for the backup. Change after a real backup is measured.
  constraint share_backups_size check (octet_length(ciphertext) <= 4194304)
);

-- share_recovery_codes ------------------------------------------------------
-- One-time recovery codes (5 for each set). Each row holds a copy of the DEK,
-- wrapped with a key derived from that recovery code.
-- used_at is set when the code is spent. A new set replaces the old set:
-- the Edge Function deletes the old rows in the same transaction.

create table public.share_recovery_codes (
  id            uuid primary key default gen_random_uuid(),
  share_id      uuid not null references public.shares (id) on delete cascade,
  code_hash     text not null check (code_hash ~ '^[0-9a-f]{64}$'),
  wrapped_dek   bytea not null,
  used_at       timestamptz,
  created_at    timestamptz not null default now(),
  unique (share_id, code_hash)
);

create index share_recovery_codes_share_id_idx
  on public.share_recovery_codes (share_id);

-- share_upload_log ----------------------------------------------------------
-- Rate limit input for the Edge Function. One row for each upload attempt.
-- client_hash is a salted hash of the client IP address, never the address.

create table public.share_upload_log (
  id           bigint generated always as identity primary key,
  client_hash  text not null,
  at           timestamptz not null default now()
);

create index share_upload_log_client_at_idx
  on public.share_upload_log (client_hash, at);

-- Row Level Security --------------------------------------------------------

alter table public.shares               enable row level security;
alter table public.share_aliases        enable row level security;
alter table public.reserved_codes       enable row level security;
alter table public.share_backups        enable row level security;
alter table public.share_recovery_codes enable row level security;
alter table public.share_upload_log     enable row level security;

-- Public lookup -------------------------------------------------------------
-- Accepts a code or an alias, in any case, with or without the dash.
-- Returns no row when the code is not known or the share has expired.

create or replace function public.get_share(lookup_code text)
returns table (
  code          text,
  progress      jsonb,
  data_as_of    timestamptz,
  shared_at     timestamptz,
  expires_at    timestamptz,
  is_permanent  boolean
)
language sql
stable
security definer
set search_path = public
as $$
  with wanted as (select public.normalize_share_code(lookup_code) as c)
  select s.code, s.progress, s.data_as_of, s.shared_at, s.expires_at, s.is_permanent
  from public.shares s, wanted w
  where (s.code = w.c
         or s.id = (select a.share_id from public.share_aliases a where a.alias = w.c))
    and (s.is_permanent or s.expires_at > now())
  limit 1;
$$;

revoke all on function public.get_share(text) from public;
grant execute on function public.get_share(text) to anon, authenticated;

-- Recovery claim (service role only) ---------------------------------------
-- One transaction: spend the recovery code, set the new owner key hash,
-- and store the data key wrapped with the new owner key.
-- After a claim, the old owner key does not work (one owner key per share).
-- Returns false when the code is not valid, already used, or the share
-- has expired. Nothing changes in that case.

create or replace function public.claim_recovery(
  p_share_id               uuid,
  p_code_hash              text,
  p_new_owner_key_hash     text,
  p_new_owner_wrapped_dek  bytea
)
returns boolean
language plpgsql
set search_path = public
as $$
begin
  if not exists (
    select 1 from public.shares s
    where s.id = p_share_id and (s.is_permanent or s.expires_at > now())
  ) then
    return false;
  end if;

  update public.share_recovery_codes
     set used_at = now()
   where share_id = p_share_id
     and code_hash = p_code_hash
     and used_at is null;
  if not found then
    return false;
  end if;

  update public.shares
     set owner_key_hash = p_new_owner_key_hash
   where id = p_share_id;

  update public.share_backups
     set owner_wrapped_dek = p_new_owner_wrapped_dek,
         updated_at = now()
   where share_id = p_share_id;

  return true;
end;
$$;

revoke all on function public.claim_recovery(uuid, text, text, bytea) from public, anon, authenticated;
grant execute on function public.claim_recovery(uuid, text, text, bytea) to service_role;

-- Replace recovery set (service role only) ---------------------------------
-- One transaction: delete every recovery code of the share (used and unused),
-- then insert the new set. The old codes stop working.
-- p_codes is a JSON array of 5 objects:
--   { "code_hash": "<64 hex>", "wrapped_dek": "<hex, no \x prefix>" }
-- Returns false when the share has expired. Nothing changes in that case.

create or replace function public.replace_recovery_codes(
  p_share_id  uuid,
  p_codes     jsonb
)
returns boolean
language plpgsql
set search_path = public
as $$
begin
  if jsonb_typeof(p_codes) <> 'array' or jsonb_array_length(p_codes) <> 5 then
    raise exception 'p_codes must be an array of 5 objects';
  end if;

  if not exists (
    select 1 from public.shares s
    where s.id = p_share_id and (s.is_permanent or s.expires_at > now())
  ) then
    return false;
  end if;

  delete from public.share_recovery_codes where share_id = p_share_id;

  insert into public.share_recovery_codes (share_id, code_hash, wrapped_dek)
  select p_share_id, e->>'code_hash', decode(e->>'wrapped_dek', 'hex')
  from jsonb_array_elements(p_codes) as e;

  return true;
end;
$$;

revoke all on function public.replace_recovery_codes(uuid, jsonb) from public, anon, authenticated;
grant execute on function public.replace_recovery_codes(uuid, jsonb) to service_role;

-- Admin rename (service role only) -----------------------------------------
-- One transaction. Gives a live share a custom code and makes it permanent.
--   * p_code can be the current code or an alias of the share.
--   * The current code becomes an alias and goes into reserved_codes.
--   * The new custom code also goes into reserved_codes, so it is never
--     issued again, also after the share is deleted.
--   * The owner key does not change, so the player keeps control.
-- Returns one status word:
--   'ok'        the rename is done
--   'invalid'   p_new_code is not 1 to 8 letters and digits
--   'not_found' no share has p_code
--   'expired'   the share has expired
--   'same'      p_new_code is already the current code
--   'taken'     p_new_code is a code, an alias or a reserved code

create or replace function public.rename_share(
  p_code      text,
  p_new_code  text
)
returns text
language plpgsql
set search_path = public
as $$
declare
  v_code  text := public.normalize_share_code(p_code);
  v_new   text := public.normalize_share_code(p_new_code);
  v_share public.shares%rowtype;
begin
  if v_new !~ '^[A-Z0-9]{1,8}$' then
    return 'invalid';
  end if;

  select * into v_share from public.shares
   where code = v_code
      or id = (select a.share_id from public.share_aliases a where a.alias = v_code)
   for update;
  if not found then
    return 'not_found';
  end if;
  if not (v_share.is_permanent or v_share.expires_at > now()) then
    return 'expired';
  end if;
  if v_new = v_share.code then
    return 'same';
  end if;

  if exists (select 1 from public.shares         where code  = v_new)
  or exists (select 1 from public.share_aliases  where alias = v_new)
  or exists (select 1 from public.reserved_codes where code  = v_new) then
    return 'taken';
  end if;

  insert into public.share_aliases (alias, share_id) values (v_share.code, v_share.id);
  insert into public.reserved_codes (code, reason)
  values (v_share.code, 'alias'), (v_new, 'custom')
  on conflict (code) do nothing;

  update public.shares
     set code = v_new,
         is_custom = true,
         is_permanent = true,
         expires_at = null
   where id = v_share.id;

  return 'ok';
exception
  when unique_violation then
    return 'taken';
end;
$$;

revoke all on function public.rename_share(text, text) from public, anon, authenticated;
grant execute on function public.rename_share(text, text) to service_role;

-- Admin re-key (service role only) -----------------------------------------
-- For a player who lost the owner key AND all recovery codes. Haven checks
-- the player's identity on Discord first. One transaction:
--   * Sets the new owner key hash. The old owner key stops working.
--   * Deletes the backup and all recovery codes. The new owner key cannot
--     unlock the old backup, and the next upload from the new browser makes
--     a new data key, so old recovery codes would unlock nothing.
--   * Keeps the code, its aliases, the public progress and the permanent flag.
-- After a re-key, the new browser uploads (this stores a new backup) and then
-- makes a new recovery set.
-- Returns one status word: 'ok', 'not_found' or 'expired'.

create or replace function public.rekey_share(
  p_code                text,
  p_new_owner_key_hash  text
)
returns text
language plpgsql
set search_path = public
as $$
declare
  v_code  text := public.normalize_share_code(p_code);
  v_share public.shares%rowtype;
begin
  select * into v_share from public.shares
   where code = v_code
      or id = (select a.share_id from public.share_aliases a where a.alias = v_code)
   for update;
  if not found then
    return 'not_found';
  end if;
  if not (v_share.is_permanent or v_share.expires_at > now()) then
    return 'expired';
  end if;

  update public.shares
     set owner_key_hash = p_new_owner_key_hash
   where id = v_share.id;

  delete from public.share_backups        where share_id = v_share.id;
  delete from public.share_recovery_codes where share_id = v_share.id;

  return 'ok';
end;
$$;

revoke all on function public.rekey_share(text, text) from public, anon, authenticated;
grant execute on function public.rekey_share(text, text) to service_role;

-- Cleanup jobs (pg_cron) ----------------------------------------------------
-- Every 15 minutes: delete expired shares. Cascades remove the backup,
-- the aliases and the recovery codes. reserved_codes rows stay.
-- Every day: delete upload log rows older than 1 day.

select cron.schedule(
  'lunar-delete-expired-shares',
  '*/15 * * * *',
  $$ delete from public.shares
     where not is_permanent and expires_at < now() $$
);

select cron.schedule(
  'lunar-trim-upload-log',
  '17 3 * * *',
  $$ delete from public.share_upload_log
     where at < now() - interval '1 day' $$
);
